/**
 * Unit tests for runtime secret/config resolution: TTL caching, readiness, consumers.
 *
 * Each test loads the secrets service afresh, reads its secrets from an in-memory
 * backend and its time from a deterministic clock, so TTL boundaries are exact and
 * no backend is reached.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */
import type { SecretReferenceEntry } from '../src/realestate_mortgage_mock/secrets/secrets.config';
import { ConfigBackend, RemoteConfigClient } from '../src/config/remoteConfig';

type SecretsServiceModule = typeof import('../src/realestate_mortgage_mock/secrets/secrets.service');
type RuntimeReadinessModule = typeof import('../src/config/runtimeReadiness');

const NANOSECONDS_PER_MILLISECOND = 1_000_000n;
const MILLISECONDS_PER_SECOND = 1000;

/** A deterministic, advance-able monotonic clock. */
class InMemoryClock {
  private nowNs = 0n;

  now(): bigint {
    return this.nowNs;
  }

  advance(seconds: number): void {
    this.nowNs += BigInt(Math.round(seconds * MILLISECONDS_PER_SECOND)) * NANOSECONDS_PER_MILLISECOND;
  }
}

/** An in-memory secret backend: values by rendered name, an outage switch, a read count. */
class InMemorySecretBackend {
  readonly values = new Map<string, string>();
  fail = false;
  readCount = 0;

  async fetch(entry: SecretReferenceEntry): Promise<string | undefined> {
    this.readCount += 1;
    if (this.fail) {
      throw new Error('backend unavailable');
    }
    return this.values.get(entry.renderedName);
  }
}

interface Resolver {
  getSecret(handle: string): Promise<string>;
  invalidate(handle: string, reason: string): void;
}

/**
 * A freshly loaded secrets service whose handles all carry `ttlSeconds`, reading from
 * `backend` on `clock`'s time.
 */
function loadResolver(
  backend: InMemorySecretBackend,
  clock: InMemoryClock,
  handles: readonly string[],
  ttlSeconds: number,
): Resolver {
  let resolver: Resolver | undefined;
  jest.isolateModules(() => {
    const manifest = require('../src/realestate_mortgage_mock/secrets/secrets.manifest') as {
      SECRET_REFERENCES: Map<string, SecretReferenceEntry>;
      FAIL_CLOSED_ON_SECRET_REFRESH: boolean;
    };
    manifest.SECRET_REFERENCES.clear();
    for (const handle of handles) {
      manifest.SECRET_REFERENCES.set(handle, { renderedName: handle, required: true, ttlSeconds });
    }
    manifest.FAIL_CLOSED_ON_SECRET_REFRESH = false;
    const backendModule = require('../src/realestate_mortgage_mock/secrets/secrets.backend') as {
      fetchSecret(entry: SecretReferenceEntry): Promise<string | undefined>;
    };
    jest.spyOn(backendModule, 'fetchSecret').mockImplementation((entry) => backend.fetch(entry));
    const serviceModule = require('../src/realestate_mortgage_mock/secrets/secrets.service') as SecretsServiceModule;
    const service = new serviceModule.SecretsService();
    resolver = {
      getSecret: (handle) => service.getSecret(handle),
      invalidate: (handle, reason) => serviceModule.invalidateSecret(handle, reason),
    };
  });
  jest.spyOn(process.hrtime, 'bigint').mockImplementation(() => clock.now());
  if (resolver === undefined) {
    throw new Error('The secrets service module did not load.');
  }
  return resolver;
}

/** An in-memory config backend: one profile map, an outage switch, a read count. */
class InMemoryConfigBackend implements ConfigBackend {
  fail = false;
  readCount = 0;

  async fetchProfile(_profile: string): Promise<Record<string, unknown>> {
    this.readCount += 1;
    if (this.fail) {
      throw new Error('backend unavailable');
    }
    return {};
  }

  describeSource(): string {
    return 'in-test in-memory config backend';
  }
}

afterEach(() => {
  jest.restoreAllMocks();
});

describe('TTL secret resolution', () => {
  it("ttl_readiness/fresh_hit", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('api_key', 'secret-v1');
    const resolver = loadResolver(backend, clock, ['api_key'], 60);

    expect(await resolver.getSecret('api_key')).toBe('secret-v1');
    const readsAfterFirst = backend.readCount;
    clock.advance(30);
    expect(await resolver.getSecret('api_key')).toBe('secret-v1');
    expect(backend.readCount).toBe(readsAfterFirst);
  });

  it("ttl_readiness/expired_refresh", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('db_password', 'pass-v1');
    const resolver = loadResolver(backend, clock, ['db_password'], 10);

    expect(await resolver.getSecret('db_password')).toBe('pass-v1');
    const readsAfterFirst = backend.readCount;
    clock.advance(15);
    backend.values.set('db_password', 'pass-v2');
    expect(await resolver.getSecret('db_password')).toBe('pass-v2');
    expect(backend.readCount).toBeGreaterThan(readsAfterFirst);
  });

  it("ttl_readiness/expired_single_flight", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('jwt_key', 'key-v1');
    const resolver = loadResolver(backend, clock, ['jwt_key'], 5);

    await resolver.getSecret('jwt_key');
    clock.advance(10);
    const readsAtExpiry = backend.readCount;
    const results = await Promise.all([
      resolver.getSecret('jwt_key'),
      resolver.getSecret('jwt_key'),
      resolver.getSecret('jwt_key'),
      resolver.getSecret('jwt_key'),
    ]);
    expect(results).toEqual(['key-v1', 'key-v1', 'key-v1', 'key-v1']);
    expect(backend.readCount - readsAtExpiry).toBe(1);
  });

  it("ttl_readiness/refresh_failure_serves_stale", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('smtp_pass', 'stale-value');
    const resolver = loadResolver(backend, clock, ['smtp_pass'], 10);

    expect(await resolver.getSecret('smtp_pass')).toBe('stale-value');
    clock.advance(15);
    backend.fail = true;
    expect(await resolver.getSecret('smtp_pass')).toBe('stale-value');
  });

  it("ttl_readiness/initial_miss_raises", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.fail = true;
    const resolver = loadResolver(backend, clock, ['missing_handle'], 30);

    await expect(resolver.getSecret('missing_handle')).rejects.toThrow();
  });

  it("ttl_readiness/zero_ttl_no_expiry", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('static_key', 'permanent-value');
    const resolver = loadResolver(backend, clock, ['static_key'], 0);

    expect(await resolver.getSecret('static_key')).toBe('permanent-value');
    const readsAfterFirst = backend.readCount;
    clock.advance(999_999);
    expect(await resolver.getSecret('static_key')).toBe('permanent-value');
    expect(backend.readCount).toBe(readsAfterFirst);
  });

  it("ttl_readiness/reactive_early_refresh_single_retry", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('api_token', 'token-v1');
    const resolver = loadResolver(backend, clock, ['api_token'], 300);

    expect(await resolver.getSecret('api_token')).toBe('token-v1');
    backend.values.set('api_token', 'token-v2');
    resolver.invalidate('api_token', 'credential-rejected');
    expect(await resolver.getSecret('api_token')).toBe('token-v2');
  });

  it("ttl_readiness/consumer_observable_refresh", async () => {
    const clock = new InMemoryClock();
    const backend = new InMemorySecretBackend();
    backend.values.set('conn_string', 'conn-v1');
    const resolver = loadResolver(backend, clock, ['conn_string'], 10);

    expect(await resolver.getSecret('conn_string')).toBe('conn-v1');
    clock.advance(15);
    backend.values.set('conn_string', 'conn-v2');
    // A resolve-on-access consumer sees the rotated value on its next read...
    const rotated = await resolver.getSecret('conn_string');
    expect(rotated).toBe('conn-v2');
    // ...and a rebuild/reconnect consumer rebuilds when the value it last saw changes.
    let lastSeen = 'conn-v1';
    let rebuilt = false;
    const rebuildOnChange = (value: string): void => {
      if (value !== lastSeen) {
        rebuilt = true;
        lastSeen = value;
      }
    };
    rebuildOnChange(rotated);
    expect(rebuilt).toBe(true);
  });
});

describe('Config re-read', () => {
  it("ttl_readiness/config_targeted_reread_fail_open", async () => {
    const backend = new InMemoryConfigBackend();
    const client = new RemoteConfigClient(backend, {}, { failOpen: true, pollSeconds: 3600 });
    await client.refresh();
    const lastKnown = JSON.stringify((client as unknown as { cache: unknown }).cache);

    backend.fail = true;
    await expect(client.refresh()).resolves.toBeUndefined();
    expect(JSON.stringify((client as unknown as { cache: unknown }).cache)).toBe(lastKnown);
    expect(backend.readCount).toBeGreaterThanOrEqual(2);
  });
});

describe('Runtime readiness', () => {
  it("ttl_readiness/strict_readiness_check", () => {
    const { ReadinessStatus, readinessFailures } =
      require('../src/config/runtimeReadiness') as RuntimeReadinessModule;
    type ReadinessReport = Parameters<typeof readinessFailures>[0];
    const okReport: ReadinessReport = {
      ok: true,
      items: [
        { kind: 'secret', logicalName: 'db_pass', renderedName: 'app/db_pass', status: ReadinessStatus.OK, detail: '' },
        { kind: 'config', logicalName: 'feature_flag', renderedName: 'features.flag', status: ReadinessStatus.OK, detail: '' },
      ],
    };
    expect(okReport.ok).toBe(true);
    expect(readinessFailures(okReport)).toEqual([]);

    const failReport: ReadinessReport = {
      ok: false,
      items: [
        { kind: 'secret', logicalName: 'db_pass', renderedName: 'app/db_pass', status: ReadinessStatus.OK, detail: '' },
        {
          kind: 'secret',
          logicalName: 'missing_key',
          renderedName: 'app/missing_key',
          status: ReadinessStatus.MISSING,
          detail: 'key not found in backend',
        },
      ],
    };
    expect(failReport.ok).toBe(false);
    const failures = readinessFailures(failReport);
    expect(failures).toHaveLength(1);
    expect(failures[0].logicalName).toBe('missing_key');
    expect(failures[0].status).toBe(ReadinessStatus.MISSING);
  });
});
